-- 037_alphabet_letter_audio.sql
-- Reworks l0 (Alphabet) quiz to use the letter's own isolated-sound
-- recording (src/assets/alphabet/*.mp4, via the new letterAudio.js util)
-- instead of requiring the example word to have its own separate
-- recording. This raises real-audio coverage from 17 to 32 of 33
-- letters (only 'ə' has no recording anywhere, letter or word — it
-- stays text-only in the match questions, which don't need audio).

delete from public.lesson_questions where lesson_id = 'l0';




delete from public.lesson_flashcards where lesson_id = 'l0';
